import{_ as a,c as t,o,aj as s}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Interface: DocumentIngestsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentIngestsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentIngestsAPI.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/DocumentIngestsAPI.md"};function r(d,e,c,i,h,l){return o(),t("div",null,[...e[0]||(e[0]=[s('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentIngestsAPI</p><h1 id="interface-documentingestsapi" tabindex="-1">Interface: DocumentIngestsAPI <a class="header-anchor" href="#interface-documentingestsapi" aria-label="Permalink to “Interface: DocumentIngestsAPI”">​</a></h1><p>Bulk loads of a large document. Accessed as <code>client.documents.ingests</code>.</p><p>A bulk load replaces a large document&#39;s records with the contents of an artifact, without taking it offline: the copy runs beside the live table and the swap is one transaction. Connected clients converge on the result rather than reloading it.</p><p>The verbs are thin — one request each — and the whole session is driven from them: <a href="#create">create</a> opens it, <a href="#uploadchunk">uploadChunk</a> sends the artifact a chunk at a time, <a href="#commit">commit</a> freezes the manifest and starts the pipeline, and <a href="#get">get</a> reports progress until the session is terminal. <a href="#abort">abort</a> gives up and sweeps what was uploaded.</p><p><code>primitive documents ingest</code> is the same sequence from a terminal, and is what most operators should reach for; these exist for an application that has to drive one itself.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="abort" tabindex="-1">abort() <a class="header-anchor" href="#abort" aria-label="Permalink to “abort()”">​</a></h3><blockquote><p><strong>abort</strong>(<code>documentId</code>, <code>sessionId</code>): <code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p></blockquote><p>Give up on a session and sweep what it uploaded.</p><p>Safe at any point before the swap; afterwards the load has landed and there is nothing to abort.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The document being loaded into</p><h5 id="sessionid" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session to abandon</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p><hr><h3 id="commit" tabindex="-1">commit() <a class="header-anchor" href="#commit" aria-label="Permalink to “commit()”">​</a></h3><blockquote><p><strong>commit</strong>(<code>documentId</code>, <code>sessionId</code>): <code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p></blockquote><p>Freeze the session&#39;s manifest and start the pipeline.</p><p>Returns as soon as the session is committed; the copy, the apply, the reconcile and the swap run on the document&#39;s own alarm afterwards. Poll <a href="#get">get</a> until the session reports <code>complete</code> or <code>failed</code>.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-1" tabindex="-1">documentId <a class="header-anchor" href="#documentid-1" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The document being loaded into</p><h5 id="sessionid-1" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-1" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session to commit</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p><hr><h3 id="create" tabindex="-1">create() <a class="header-anchor" href="#create" aria-label="Permalink to “create()”">​</a></h3><blockquote><p><strong>create</strong>(<code>documentId</code>): <code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p></blockquote><p>Open a bulk-load session on a document.</p><p>Refused with <code>DOCUMENT_INGEST_ACTIVE</code> while another session on the same document is still running — one at a time, because a session owns the document&#39;s staging tables.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-2" tabindex="-1">documentId <a class="header-anchor" href="#documentid-2" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The large document to load into</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>documentId</code>, <code>sessionId</code>): <code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p></blockquote><p>One session&#39;s state and progress.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-3" tabindex="-1">documentId <a class="header-anchor" href="#documentid-3" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The document the session belongs to</p><h5 id="sessionid-2" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-2" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session to read</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentIngestSession.html"><code>DocumentIngestSession</code></a>&gt;</p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>(<code>documentId</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./DocumentIngestPage.html"><code>DocumentIngestPage</code></a>&gt;</p></blockquote><p>A document&#39;s bulk-load sessions, newest first.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-4" tabindex="-1">documentId <a class="header-anchor" href="#documentid-4" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The document whose sessions to list</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p>Page size and cursor</p><h6 id="cursor" tabindex="-1">cursor? <a class="header-anchor" href="#cursor" aria-label="Permalink to “cursor?”">​</a></h6><p><code>string</code></p><h6 id="limit" tabindex="-1">limit? <a class="header-anchor" href="#limit" aria-label="Permalink to “limit?”">​</a></h6><p><code>number</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentIngestPage.html"><code>DocumentIngestPage</code></a>&gt;</p><hr><h3 id="uploadchunk" tabindex="-1">uploadChunk() <a class="header-anchor" href="#uploadchunk" aria-label="Permalink to “uploadChunk()”">​</a></h3><blockquote><p><strong>uploadChunk</strong>(<code>documentId</code>, <code>sessionId</code>, <code>chunk</code>): <code>Promise</code>&lt;<a href="./DocumentIngestChunkUploadResult.html"><code>DocumentIngestChunkUploadResult</code></a>&gt;</p></blockquote><p>Upload one chunk of the artifact.</p><p>The descriptor travels with the bytes and the server checks both: a body whose length or SHA-256 does not match what the descriptor claims is refused before anything is stored. Ids must ascend within a chunk, and a model&#39;s chunks must ascend and not overlap in <code>index</code> order.</p><p>Answers for the chunk, not for the session: the accepted byte length and the chunk&#39;s place among the ones stored so far.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-5" tabindex="-1">documentId <a class="header-anchor" href="#documentid-5" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The document being loaded into</p><h5 id="sessionid-3" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-3" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session this chunk belongs to</p><h5 id="chunk" tabindex="-1">chunk <a class="header-anchor" href="#chunk" aria-label="Permalink to “chunk”">​</a></h5><p><a href="./DocumentIngestChunkUpload.html"><code>DocumentIngestChunkUpload</code></a></p><p>The chunk&#39;s descriptor and its stored bytes</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentIngestChunkUploadResult.html"><code>DocumentIngestChunkUploadResult</code></a>&gt;</p>',94)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
